support.sql:
-- Telegram-native operator user-management center.

ALTER TABLE conversations ADD COLUMN panel_message_id INTEGER;

ALTER TABLE user_abuse_state ADD COLUMN manual_restricted_until TEXT;
ALTER TABLE user_abuse_state ADD COLUMN manual_restriction_reason TEXT;
ALTER TABLE user_abuse_state ADD COLUMN manual_restriction_notice_at TEXT;

ALTER TABLE banned_users ADD COLUMN banned_by INTEGER;
ALTER TABLE banned_users ADD COLUMN banned_by_name TEXT;
ALTER TABLE banned_users ADD COLUMN notified_at TEXT;

CREATE TABLE IF NOT EXISTS operator_audit (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  bot_id TEXT NOT NULL,
  user_id INTEGER,
  actor_type TEXT NOT NULL CHECK(actor_type IN ('operator', 'system')),
  operator_id INTEGER,
  operator_name TEXT,
  action TEXT NOT NULL,
  duration_seconds INTEGER,
  reason TEXT,
  result TEXT NOT NULL,
  created_at TEXT NOT NULL,
  CHECK(actor_type <> 'operator' OR operator_id IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS operator_audit_time_idx
  ON operator_audit(created_at DESC);
CREATE INDEX IF NOT EXISTS operator_audit_bot_user_idx
  ON operator_audit(bot_id, user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS operator_audit_operator_idx
  ON operator_audit(operator_id, created_at DESC);

-- One pending interactive flow per operator prevents old confirmation buttons
-- from applying to a newer target or service.
CREATE TABLE IF NOT EXISTS operator_pending_actions (
  operator_id INTEGER PRIMARY KEY,
  operator_name TEXT NOT NULL,
  management_bot_id TEXT NOT NULL,
  target_bot_id TEXT,
  user_id INTEGER,
  action TEXT NOT NULL,
  stage TEXT NOT NULL CHECK(stage IN ('service', 'reason', 'duration', 'confirm', 'executing')),
  duration_seconds INTEGER,
  reason TEXT,
  chat_id INTEGER NOT NULL,
  thread_id INTEGER,
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS operator_pending_actions_expiry_idx
  ON operator_pending_actions(expires_at);

CREATE INDEX IF NOT EXISTS user_abuse_state_management_idx
  ON user_abuse_state(bot_id, manual_restricted_until, muted_until, verification_required, risk_score);

-- Per-service reaction switch and live Telegram capability gate.
-- capability_verified must only be set after the documented end-to-end Telegram test.
CREATE TABLE IF NOT EXISTS reaction_settings (
  bot_id TEXT PRIMARY KEY,
  enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0, 1)),
  capability_verified INTEGER NOT NULL DEFAULT 0 CHECK(capability_verified IN (0, 1)),
  unavailable_reason TEXT,
  updated_at TEXT NOT NULL,
  verified_at TEXT
);

-- Keep only the newest mirrored update in each direction on the existing mapping.
-- These are ordering fences, not a per-reaction history.
ALTER TABLE message_mappings ADD COLUMN user_reaction_update_id INTEGER;
ALTER TABLE message_mappings ADD COLUMN support_reaction_update_id INTEGER;
ALTER TABLE message_mappings ADD COLUMN user_reaction_date INTEGER;
ALTER TABLE message_mappings ADD COLUMN support_reaction_date INTEGER;

-- Short leases serialize one message/direction while Telegram is being updated.
CREATE TABLE IF NOT EXISTS reaction_sync_locks (
  mapping_id INTEGER NOT NULL,
  direction TEXT NOT NULL CHECK(direction IN ('user_to_support', 'support_to_user')),
  owner_token TEXT NOT NULL,
  lease_expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY(mapping_id, direction)
);

-- One global lease serializes webhook subscription changes across services.
CREATE TABLE IF NOT EXISTS reaction_settings_lock (
  id INTEGER PRIMARY KEY CHECK(id = 1),
  owner_token TEXT NOT NULL,
  lease_expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS message_mappings_support_reaction_lookup_idx
  ON message_mappings(support_message_id)
  WHERE support_message_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS reaction_sync_locks_expiry_idx ON reaction_sync_locks(lease_expires_at);

-- Deep bug-hunt hardening: bind interactive confirmations to a single flow.
ALTER TABLE operator_pending_actions ADD COLUMN flow_nonce TEXT;

-- Existing pending screens become intentionally stale after this migration.
UPDATE operator_pending_actions SET flow_nonce = 'legacy-' || operator_id WHERE flow_nonce IS NULL;

CREATE INDEX IF NOT EXISTS operator_pending_actions_nonce_idx
  ON operator_pending_actions(operator_id, flow_nonce, expires_at);

-- Second bug-hunt: ordering and destructive-flow replay fences.
ALTER TABLE conversations ADD COLUMN topic_state_update_id INTEGER;
CREATE TABLE IF NOT EXISTS operator_completed_flows (flow_nonce TEXT PRIMARY KEY, operator_id INTEGER NOT NULL, action TEXT NOT NULL, completed_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS operator_completed_flows_operator_idx ON operator_completed_flows(operator_id, completed_at);

-- Third bug-hunt hardening: safe pending albums and stale operator-flow fencing.
-- Existing queued rows keep these media columns NULL and safely fall back to per-message delivery.
ALTER TABLE pending_messages ADD COLUMN media_type TEXT;
ALTER TABLE pending_messages ADD COLUMN file_id TEXT;
ALTER TABLE pending_messages ADD COLUMN caption TEXT;
ALTER TABLE operator_pending_actions ADD COLUMN expected_state_key TEXT;

-- Third bug-hunt reliability hardening: durable external-delivery fences and Telegram album metadata.
ALTER TABLE media_groups ADD COLUMN delivery_started_at TEXT;
ALTER TABLE media_groups ADD COLUMN delivery_completed_at TEXT;
ALTER TABLE media_group_items ADD COLUMN delivered_at TEXT;
ALTER TABLE media_group_items ADD COLUMN caption_entities_json TEXT;
ALTER TABLE media_group_items ADD COLUMN has_spoiler INTEGER NOT NULL DEFAULT 0 CHECK(has_spoiler IN (0, 1));

ALTER TABLE pending_messages ADD COLUMN delivery_started_at TEXT;
ALTER TABLE pending_messages ADD COLUMN delivery_completed_at TEXT;
ALTER TABLE pending_messages ADD COLUMN caption_entities_json TEXT;
ALTER TABLE pending_messages ADD COLUMN has_spoiler INTEGER NOT NULL DEFAULT 0 CHECK(has_spoiler IN (0, 1));

CREATE INDEX IF NOT EXISTS media_groups_delivery_idx
  ON media_groups(bot_id, delivery_started_at, delivery_completed_at, last_received_at);
CREATE INDEX IF NOT EXISTS pending_messages_delivery_idx
  ON pending_messages(bot_id, user_id, delivery_started_at, delivery_completed_at, delivered_at, failed_at, id);

-- Fourth deep bug-hunt: single-message/provisioning fences, mapping repair, and uncertain-delivery retention.
ALTER TABLE processed_updates ADD COLUMN dispatch_succeeded_at TEXT;

CREATE TABLE IF NOT EXISTS conversation_provision_attempts (
  bot_id TEXT NOT NULL,
  user_id INTEGER NOT NULL,
  started_at TEXT NOT NULL,
  completed_at TEXT,
  thread_id INTEGER,
  failure_code TEXT,
  failure_detail TEXT,
  alerted_at TEXT,
  PRIMARY KEY (bot_id, user_id)
);

CREATE TABLE IF NOT EXISTS message_delivery_attempts (
  bot_id TEXT NOT NULL,
  direction TEXT NOT NULL CHECK(direction IN ('user_to_support', 'support_to_user')),
  source_chat_id INTEGER NOT NULL,
  source_message_id INTEGER NOT NULL,
  user_id INTEGER NOT NULL,
  thread_id INTEGER NOT NULL,
  target_chat_id INTEGER NOT NULL,
  method TEXT NOT NULL,
  started_at TEXT NOT NULL,
  completed_at TEXT,
  target_message_id INTEGER,
  failure_code TEXT,
  failure_detail TEXT,
  alerted_at TEXT,
  mapping_synced_at TEXT,
  PRIMARY KEY (bot_id, direction, source_chat_id, source_message_id)
);
CREATE INDEX IF NOT EXISTS message_delivery_repair_idx ON message_delivery_attempts(bot_id, completed_at, mapping_synced_at);
CREATE INDEX IF NOT EXISTS message_delivery_unknown_idx ON message_delivery_attempts(bot_id, failure_code, alerted_at, started_at);

ALTER TABLE media_groups ADD COLUMN delivery_uncertain_at TEXT;
ALTER TABLE media_groups ADD COLUMN delivery_alerted_at TEXT;
ALTER TABLE media_group_items ADD COLUMN target_message_id INTEGER;
ALTER TABLE media_group_items ADD COLUMN mapping_synced_at TEXT;
ALTER TABLE pending_messages ADD COLUMN target_message_id INTEGER;
ALTER TABLE pending_messages ADD COLUMN target_thread_id INTEGER;
ALTER TABLE pending_messages ADD COLUMN mapping_synced_at TEXT;

CREATE INDEX IF NOT EXISTS media_groups_uncertain_idx ON media_groups(bot_id, delivery_completed_at, delivery_uncertain_at, delivery_alerted_at, last_received_at);

-- Fifth deep bug-hunt: distinguish durable preparation from an external request attempt,
-- isolate ambiguous album items, add pending-alert observability, and remove the
-- General control-plane single point of failure.

ALTER TABLE conversation_provision_attempts ADD COLUMN request_started_at TEXT;
ALTER TABLE message_delivery_attempts ADD COLUMN request_started_at TEXT;
ALTER TABLE media_groups ADD COLUMN request_started_at TEXT;
ALTER TABLE media_group_items ADD COLUMN delivery_attempt_started_at TEXT;
ALTER TABLE media_group_items ADD COLUMN delivery_uncertain_at TEXT;
ALTER TABLE pending_messages ADD COLUMN request_started_at TEXT;
ALTER TABLE pending_messages ADD COLUMN failure_alerted_at TEXT;

CREATE INDEX IF NOT EXISTS media_group_items_delivery_state_idx
  ON media_group_items(bot_id, direction, media_group_id, source_chat_id, delivered_at, delivery_uncertain_at, delivery_attempt_started_at);

CREATE INDEX IF NOT EXISTS pending_messages_uncertain_alert_idx
  ON pending_messages(bot_id, failure_code, failure_alerted_at, failed_at);

CREATE TABLE IF NOT EXISTS general_message_claims (
  support_group_id INTEGER NOT NULL,
  message_id INTEGER NOT NULL,
  handler_bot_id TEXT NOT NULL,
  owner_token TEXT NOT NULL,
  lease_expires_at TEXT NOT NULL,
  completed_at TEXT,
  created_at TEXT NOT NULL,
  PRIMARY KEY (support_group_id, message_id)
);

CREATE INDEX IF NOT EXISTS general_message_claims_cleanup_idx
  ON general_message_claims(completed_at, lease_expires_at, created_at);

-- Sixth full bug hunt: operator revocation linearization, reopen recovery fencing,
-- durable reopen business delivery, and legacy album quarantine.

CREATE TABLE IF NOT EXISTS support_operator_execution_locks (
  operator_id INTEGER PRIMARY KEY,
  owner_token TEXT NOT NULL,
  lease_expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS support_operator_execution_locks_expiry_idx
  ON support_operator_execution_locks(lease_expires_at);

ALTER TABLE conversation_reopen_effects ADD COLUMN recovery_owner_token TEXT;
ALTER TABLE conversation_reopen_effects ADD COLUMN recovery_lease_expires_at TEXT;
ALTER TABLE conversation_reopen_effects ADD COLUMN marker_prepared_at TEXT;
ALTER TABLE conversation_reopen_effects ADD COLUMN last_business_queued_at TEXT;
ALTER TABLE conversation_reopen_effects ADD COLUMN cancelled_at TEXT;
ALTER TABLE conversation_reopen_effects ADD COLUMN cancellation_reason TEXT;

ALTER TABLE operator_audit ADD COLUMN reopen_effect_id INTEGER;
CREATE UNIQUE INDEX IF NOT EXISTS operator_audit_reopen_effect_action_idx
  ON operator_audit(reopen_effect_id, action)
  WHERE reopen_effect_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS reopen_business_messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  bot_id TEXT NOT NULL,
  user_id INTEGER NOT NULL,
  update_id INTEGER NOT NULL,
  source_chat_id INTEGER NOT NULL,
  source_message_id INTEGER NOT NULL,
  reply_to_source_message_id INTEGER,
  source_username TEXT,
  source_first_name TEXT,
  source_last_name TEXT,
  media_group_id TEXT,
  media_type TEXT,
  file_id TEXT,
  caption TEXT,
  caption_entities_json TEXT,
  has_spoiler INTEGER NOT NULL DEFAULT 0 CHECK(has_spoiler IN (0, 1)),
  created_at TEXT NOT NULL,
  delivered_at TEXT,
  target_message_id INTEGER,
  failure_code TEXT,
  failure_detail TEXT,
  failure_alerted_at TEXT,
  UNIQUE(bot_id, update_id)
);
CREATE INDEX IF NOT EXISTS reopen_business_messages_recovery_idx
  ON reopen_business_messages(bot_id, user_id, delivered_at, source_message_id);

ALTER TABLE media_groups ADD COLUMN operator_identity_unknown_at TEXT;
ALTER TABLE media_groups ADD COLUMN operator_identity_alerted_at TEXT;

-- Global round-robin cursor; no bot FK, so empty registries still run retention.
CREATE TABLE recovery_scheduler (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  next_job INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS telegram_cooldowns (
  bot_key TEXT PRIMARY KEY,
  not_before TEXT NOT NULL,
  failures INTEGER NOT NULL DEFAULT 1,
  last_method TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_telegram_cooldowns_expiry ON telegram_cooldowns(not_before);

CREATE TABLE IF NOT EXISTS operational_signals (
  bot_id TEXT NOT NULL, bucket TEXT NOT NULL, kind TEXT NOT NULL,
  PRIMARY KEY(bot_id, bucket, kind)
);
CREATE TABLE IF NOT EXISTS operational_signal_budget (
  id INTEGER PRIMARY KEY CHECK(id = 1), day_utc TEXT NOT NULL DEFAULT '', used INTEGER NOT NULL DEFAULT 0
);
INSERT OR IGNORE INTO operational_signal_budget(id) VALUES(1);
-- Bound new telemetry rows account-wide, even during an attack.
CREATE TRIGGER IF NOT EXISTS operational_signal_cap BEFORE INSERT ON operational_signals
WHEN EXISTS(SELECT 1 FROM operational_signal_budget WHERE id = 1 AND day_utc = substr(NEW.bucket, 1, 10) AND used >= 1000)
BEGIN SELECT RAISE(IGNORE); END;
CREATE TRIGGER IF NOT EXISTS operational_signal_count AFTER INSERT ON operational_signals
BEGIN
  UPDATE operational_signal_budget SET used = CASE WHEN day_utc = substr(NEW.bucket, 1, 10) THEN used + 1 ELSE 1 END,
    day_utc = substr(NEW.bucket, 1, 10) WHERE id = 1;
END;
CREATE INDEX IF NOT EXISTS operational_signals_window ON operational_signals(bucket, bot_id);
CREATE INDEX IF NOT EXISTS health_delivery_pending ON message_delivery_attempts(bot_id, completed_at, started_at);
CREATE INDEX IF NOT EXISTS health_pending_ready ON pending_messages(bot_id, delivered_at, failed_at, created_at);
CREATE INDEX IF NOT EXISTS health_reopen_pending ON reopen_business_messages(bot_id, delivered_at, created_at);

-- Only idempotent deletion of bot-created service/compensation messages.
-- Never used to replay delivery of a user's message.
CREATE TABLE IF NOT EXISTS telegram_cleanup_jobs (
  bot_id TEXT NOT NULL, chat_id INTEGER NOT NULL, message_id INTEGER NOT NULL,
  created_at TEXT NOT NULL, completed_at TEXT, last_error TEXT,
  PRIMARY KEY(bot_id, chat_id, message_id)
);
CREATE INDEX IF NOT EXISTS telegram_cleanup_pending ON telegram_cleanup_jobs(bot_id, completed_at, created_at);

monitor.sql:
CREATE TABLE IF NOT EXISTS monitor_incidents (
  incident_key TEXT PRIMARY KEY,
  severity INTEGER NOT NULL DEFAULT 0,
  sent_severity INTEGER NOT NULL DEFAULT 0,
  quality TEXT NOT NULL DEFAULT 'unavailable',
  message TEXT NOT NULL DEFAULT '',
  first_seen TEXT NOT NULL,
  last_seen TEXT NOT NULL,
  last_sample TEXT,
  normal_samples INTEGER NOT NULL DEFAULT 0,
  candidate_severity INTEGER,
  last_sent TEXT,
  recovered_at TEXT,
  owner_token TEXT,
  lease_until TEXT
);
CREATE INDEX IF NOT EXISTS idx_monitor_incidents_pending ON monitor_incidents(last_sent, incident_key);

CREATE TABLE IF NOT EXISTS monitor_api_cooldowns (
  scope TEXT PRIMARY KEY,
  not_before TEXT NOT NULL,
  failures INTEGER NOT NULL DEFAULT 1,
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS telegram_cooldowns (
  bot_key TEXT PRIMARY KEY,
  not_before TEXT NOT NULL,
  failures INTEGER NOT NULL DEFAULT 1,
  last_method TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS monitor_scheduler (
  id INTEGER PRIMARY KEY CHECK(id = 1),
  next_job INTEGER NOT NULL DEFAULT 0,
  owner_token TEXT,
  lease_until TEXT
);
INSERT OR IGNORE INTO monitor_scheduler(id) VALUES(1);

CREATE TABLE IF NOT EXISTS storage_inventory (
  database_id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  inventory_id TEXT NOT NULL,
  bytes INTEGER,
  measured_at TEXT,
  quality TEXT NOT NULL DEFAULT 'unavailable'
);
CREATE INDEX IF NOT EXISTS idx_storage_inventory_generation ON storage_inventory(inventory_id, database_id);
CREATE TABLE IF NOT EXISTS storage_samples (
  resource_id TEXT NOT NULL,
  measured_at TEXT NOT NULL,
  bytes INTEGER NOT NULL CHECK(bytes >= 0),
  quality TEXT NOT NULL,
  PRIMARY KEY(resource_id, measured_at)
);
CREATE TABLE IF NOT EXISTS storage_daily_samples (
  resource_id TEXT NOT NULL,
  day_utc TEXT NOT NULL,
  measured_at TEXT NOT NULL,
  bytes INTEGER NOT NULL CHECK(bytes >= 0),
  PRIMARY KEY(resource_id, day_utc)
);
CREATE TABLE IF NOT EXISTS runtime_samples (
  script_name TEXT NOT NULL,
  window_end TEXT NOT NULL,
  payload TEXT NOT NULL,
  quality TEXT NOT NULL,
  PRIMARY KEY(script_name, window_end)
);
CREATE INDEX IF NOT EXISTS storage_samples_expiry ON storage_samples(measured_at);
CREATE INDEX IF NOT EXISTS storage_daily_expiry ON storage_daily_samples(day_utc);
CREATE INDEX IF NOT EXISTS runtime_samples_expiry ON runtime_samples(window_end);
